      "nativeSlide": {
        "id": "ib13-fda45056e7b1-s005",
        "title": "Sequence, ratio, series and partial sum",
        "layout": "single",
        "blocks": [
          {
            "id": "ib13-fda45056e7b1-s005-b01",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "A sequence lists values in order. The subscript tells us the position, beginning here with the first term."
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "ib13-fda45056e7b1-s005-b02",
            "type": "math",
            "version": 2,
            "content": {
              "source": {
                "mode": "tex",
                "tex": "u_1,u_2,u_3,\\ldots"
              },
              "spoken": "u one, u two, u three, and so on",
              "display": true
            }
          },
          {
            "id": "ib13-fda45056e7b1-s005-b03",
            "type": "math",
            "version": 2,
            "content": {
              "source": {
                "mode": "tex",
                "tex": "r=\\frac{u_{n+1}}{u_n}\\quad(u_n\\ne0)"
              },
              "spoken": "The common ratio is u sub n plus one divided by u sub n, when u sub n is nonzero",
              "display": true
            }
          },
          {
            "id": "ib13-fda45056e7b1-s005-b04",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "The recurrence describes multiplication directly, including cases where a quotient cannot be formed. Throughout this lesson, term indices are positive integers."
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "ib13-fda45056e7b1-s005-b05",
            "type": "math",
            "version": 2,
            "content": {
              "source": {
                "mode": "tex",
                "tex": "u_{n+1}=r u_n"
              },
              "spoken": "The next term equals the common ratio times the current term",
              "display": true
            }
          },
          {
            "id": "ib13-fda45056e7b1-s005-b06",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "A series adds the terms. A partial sum stops after a specified number of terms, so it is a total rather than a term at one position."
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "ib13-fda45056e7b1-s005-b07",
            "type": "math",
            "version": 2,
            "content": {
              "source": {
                "mode": "tex",
                "tex": "S_n=u_1+u_2+\\cdots+u_n"
              },
              "spoken": "S sub n is the sum of the first n terms",
              "display": true
            }
          }
        ]
      }
