      "nativeSlide": {
        "id": "ib13-fda45056e7b1-s058",
        "title": "Repeated percentage change is not simple percentage addition",
        "layout": "single",
        "blocks": [
          {
            "id": "ib13-fda45056e7b1-s058-b01",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "Three successive increases of 10 percent act on three different starting amounts. Each new amount becomes the base for the next increase."
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "ib13-fda45056e7b1-s058-b02",
            "type": "math",
            "version": 2,
            "content": {
              "source": {
                "mode": "tex",
                "tex": "1.1^3=1.331"
              },
              "spoken": "One point one cubed equals one point three three one",
              "display": true
            }
          },
          {
            "id": "ib13-fda45056e7b1-s058-b03",
            "type": "math",
            "version": 2,
            "content": {
              "source": {
                "mode": "tex",
                "tex": "1+3(0.10)=1.30"
              },
              "spoken": "One plus three times zero point one equals one point three",
              "display": true
            }
          },
          {
            "id": "ib13-fda45056e7b1-s058-b04",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "The multiplicative calculation gives 133.1 percent of the original amount, an increase of 33.1 percent. Adding three copies of 10 percent would give only 30 percent and misses the growth applied to previous increases."
                    }
                  ]
                }
              ]
            }
          }
        ]
      }
