      "nativeSlide": {
        "id": "ib13-fda45056e7b1-s063",
        "title": "Saturation and changing conditions limit extrapolation",
        "layout": "single",
        "blocks": [
          {
            "id": "ib13-fda45056e7b1-s063-b01",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "A constant multiplier describes one regime of behaviour. It can become unreliable when the conditions that produced it change."
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "ib13-fda45056e7b1-s063-b02",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "list",
                  "style": "unordered",
                  "items": [
                    {
                      "type": "list-item",
                      "children": [
                        {
                          "type": "text",
                          "text": "Physical growth may be limited by food, space or other resources."
                        }
                      ]
                    },
                    {
                      "type": "list-item",
                      "children": [
                        {
                          "type": "text",
                          "text": "An adoption model can run out of eligible new users."
                        }
                      ]
                    },
                    {
                      "type": "list-item",
                      "children": [
                        {
                          "type": "text",
                          "text": "A change in rules, bandwidth or storage policy can alter a digital growth process."
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "ib13-fda45056e7b1-s063-b03",
            "type": "rich-text",
            "version": 2,
            "content": {
              "nodes": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "type": "text",
                      "text": "State the interval or stages for which the assumptions are credible. A good fit to early observations does not justify extending exponential growth indefinitely. Explain which constraint could cause the model to fail, without claiming a new model has already been established."
                    }
                  ]
                }
              ]
            }
          }
        ]
      }
